package com.securevault.controller;
import com.securevault.entity.*;import com.securevault.repository.UserRepository;import com.securevault.security.JwtService;import com.securevault.service.*;import jakarta.servlet.http.HttpServletRequest;import org.springframework.http.*;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/auth") @CrossOrigin(origins="http://localhost:5173") public class AuthController{
 private final AuthService auth;private final UserRepository users;private final PasswordEncoder pe;private final JwtService jwt;private final MfaService mfa;private final SecurityMonitoringService monitor;private final SessionService sessions;private final DeviceService deviceService;
 public AuthController(AuthService a,UserRepository u,PasswordEncoder p,JwtService j,MfaService m,SecurityMonitoringService sm,SessionService ss,DeviceService ds){auth=a;users=u;pe=p;jwt=j;mfa=m;monitor=sm;sessions=ss;deviceService=ds;}
 @PostMapping("/register") public ResponseEntity<?> register(@RequestBody RegisterRequest r){try{auth.register(r.name(),r.email(),r.password());return ResponseEntity.ok(Map.of("message","User registered successfully"));}catch(RuntimeException e){return ResponseEntity.badRequest().body(Map.of("message",e.getMessage()));}}
 @PostMapping("/login") public ResponseEntity<?> login(@RequestBody LoginRequest r,HttpServletRequest req){User u=users.findByEmail(r.email()).orElse(null);if(u==null||!pe.matches(r.password(),u.getPassword())){if(u!=null)monitor.recordLogin(u,"FAILED",req.getRemoteAddr(),deviceService.deviceName(req.getHeader("User-Agent")),req.getHeader("User-Agent"),"Invalid credentials");return ResponseEntity.status(401).body(Map.of("message","Invalid email or password"));}if(u.isMfaEnabled())return ResponseEntity.ok(Map.of("mfaRequired",true));String token=jwt.generateToken(u.getEmail());monitor.recordLogin(u,"SUCCESS",req.getRemoteAddr(),deviceService.deviceName(req.getHeader("User-Agent")),req.getHeader("User-Agent"),"Login successful");sessions.create(u,token,req.getRemoteAddr(),req.getHeader("User-Agent"),deviceService.deviceName(req.getHeader("User-Agent")));deviceService.record(u,req);return ResponseEntity.ok(Map.of("token",token));}
 @PostMapping("/login/mfa") public ResponseEntity<?> loginMfa(@RequestBody MfaLoginRequest r,HttpServletRequest req){User u=users.findByEmail(r.email()).orElse(null);if(u==null||!pe.matches(r.password(),u.getPassword())||!u.isMfaEnabled()||!mfa.verify(u.getMfaSecret(),r.code()))return ResponseEntity.status(401).body(Map.of("message","Invalid credentials or MFA code"));String token=jwt.generateToken(u.getEmail());monitor.recordLogin(u,"SUCCESS",req.getRemoteAddr(),deviceService.deviceName(req.getHeader("User-Agent")),req.getHeader("User-Agent"),"MFA login successful");sessions.create(u,token,req.getRemoteAddr(),req.getHeader("User-Agent"),deviceService.deviceName(req.getHeader("User-Agent")));deviceService.record(u,req);return ResponseEntity.ok(Map.of("token",token));}
 @GetMapping("/me") public ResponseEntity<?> me(org.springframework.security.core.Authentication a){return ResponseEntity.ok(a.getName());}
 public record RegisterRequest(String name,String email,String password){} public record LoginRequest(String email,String password){} public record MfaLoginRequest(String email,String password,String code){}
}
